  themeLabel: { en: "Colours", pa: "ਰੰਗ" }, themeDark: { en: "Dark", pa: "ਗੂੜ੍ਹਾ" }, themeLight: { en: "Light", pa: "ਹਲਕਾ" },
  gcStart: { en: "Let's play! Take your time over every move.", pa: "ਚਲੋ ਖੇਡੀਏ! ਹਰ ਚਾਲ ਆਰਾਮ ਨਾਲ ਸੋਚ ਕੇ ਚੱਲੋ।" },
