  insWeak: { en: "You lose the most points in the {weak}: {a}% accuracy, against {b}% in the {strong}.", pa: "ਤੁਸੀਂ ਸਭ ਤੋਂ ਵੱਧ ਅੰਕ {weak} ਵਿੱਚ ਗੁਆਉਂਦੇ ਹੋ: ਸ਼ੁੱਧਤਾ {a}%, ਜਦੋਂ ਕਿ {strong} ਵਿੱਚ {b}%।" },
  insEven: { en: "Your play is even: no part of the game is much weaker than the others. Keep it up!", pa: "ਤੁਹਾਡੀ ਖੇਡ ਹਰ ਹਿੱਸੇ ਵਿੱਚ ਇੱਕੋ ਜਿਹੀ ਹੈ: ਕੋਈ ਹਿੱਸਾ ਬਾਕੀਆਂ ਨਾਲੋਂ ਬਹੁਤ ਕਮਜ਼ੋਰ ਨਹੀਂ। ਇਵੇਂ ਹੀ ਖੇਡਦੇ ਰਹੋ!" },
  insRush_fast: { en: "And when you move in under 5 seconds, your accuracy drops to {a}%.", pa: "ਅਤੇ ੫ ਸਕਿੰਟ ਤੋਂ ਘੱਟ ਸੋਚ ਕੇ ਚੱਲੀ ਚਾਲ ਦੀ ਸ਼ੁੱਧਤਾ {a}% ਰਹਿ ਜਾਂਦੀ ਹੈ।" },
  insRush_mid: { en: "And when you think for 5 to 20 seconds, your accuracy drops to {a}%.", pa: "ਅਤੇ ੫ ਤੋਂ ੨੦ ਸਕਿੰਟ ਸੋਚ ਕੇ ਚੱਲੀ ਚਾਲ ਦੀ ਸ਼ੁੱਧਤਾ {a}% ਰਹਿ ਜਾਂਦੀ ਹੈ।" },
  insRush_slow: { en: "And when you think for over 20 seconds, your accuracy drops to {a}%.", pa: "ਅਤੇ ੨੦ ਸਕਿੰਟ ਤੋਂ ਵੱਧ ਸੋਚ ਕੇ ਚੱਲੀ ਚਾਲ ਦੀ ਸ਼ੁੱਧਤਾ {a}% ਰਹਿ ਜਾਂਦੀ ਹੈ।" },
  insSlowDown: { en: "Slow down when it matters.", pa: "ਅਹਿਮ ਮੌਕੇ 'ਤੇ ਕਾਹਲੀ ਨਾ ਕਰੋ।" },
