  insPh_opening: { en: "Opening", pa: "ਸ਼ੁਰੂਆਤ" }, insPh_middlegame: { en: "Middlegame", pa: "ਵਿਚਕਾਰਲੀ ਖੇਡ" }, insPh_endgame: { en: "Endgame", pa: "ਅੰਤਲੀ ਖੇਡ" },
