  insShare: { en: "{n}% of moves", pa: "ਚਾਲਾਂ ਵਿੱਚੋਂ {n}%" },
  insNoOpenings: { en: "No named openings yet.", pa: "ਅਜੇ ਕਿਸੇ ਸ਼ੁਰੂਆਤ ਦਾ ਨਾਂ ਨਹੀਂ ਮਿਲਿਆ।" },
